    except SchemaError:
        write_out({"error": "E_SCHEMA"})
        return 0
    except Exception:
        if os.environ.get("RULE_MINER_DEBUG"):
            traceback.print_exc(file=sys.stderr)
        write_out({"error": "E_SCHEMA"})
        return 0
    write_out(response)
    return 0


if __name__ == "__main__":
    sys.exit(main())
