"""Slow, straightforward reference implementation (independent of main.py)."""
import json, sys, re
from fractions import Fraction
from itertools import combinations

def die(code):
    print(json.dumps({"error": code}))
    sys.exit(0)

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)

NAME_RE = re.compile(r"\A[a-z][a-z0-9_]{0,31}\Z")
TRACE_RE = re.compile(r"\A[A-Za-z][A-Za-z0-9_-]{0,31}\Z")
IDVAL_RE = re.compile(r"\A[A-Za-z0-9_.:-]{1,32}\Z")

def term_type(term, K, fields, allow_dollar):
    """Return (type, eval_fn)."""
    keys = set(term.keys())
    if "field" in term:
        assert keys == {"field", "at"}
        name = term["field"]; assert name in fields
        idx = [i for i,f in enumerate(fields) if f["name"]==name][0]
        at = term["at"]
        if isinstance(at, str):
            assert at == "$" and allow_dollar
            return fields[idx]["type"], (lambda ctx, b, idx=idx: ctx[b][idx])
        assert is_int(at) and 0 <= at < K
        return fields[idx]["type"], (lambda ctx, b, idx=idx, at=at: ctx[at][idx])
    if "const" in term:
        assert keys == {"const", "type"}
        t = term["type"]; v = term["const"]
        if t == "FLAG": assert isinstance(v, bool)
        elif t == "ID": assert isinstance(v, str)
        else: assert is_int(v)
        return t, (lambda ctx, b, v=v: v)
    if "scale" in term:
        assert keys == {"scale", "term"}
        f = term["scale"]; assert is_int(f) and -1024 <= f <= 1024
        t, fn = term_type(term["term"], K, fields, allow_dollar)
        assert t in ("TIME","SIZE","COUNT")
        return t, (lambda ctx, b, f=f, fn=fn: f*fn(ctx,b))
    if "add" in term:
        assert keys == {"add"}
        assert isinstance(term["add"], list) and len(term["add"])==2
        t1,f1 = term_type(term["add"][0], K, fields, allow_dollar)
        t2,f2 = term_type(term["add"][1], K, fields, allow_dollar)
        assert t1==t2 and t1 in ("TIME","SIZE","COUNT")
        return t1, (lambda ctx,b,f1=f1,f2=f2: f1(ctx,b)+f2(ctx,b))
    if "aggregate" in term:
        assert keys == {"aggregate","field","from","to"}
        op = term["aggregate"]; name = term["field"]; lo = term["from"]; hi = term["to"]
        idx = [i for i,f in enumerate(fields) if f["name"]==name][0]
        assert fields[idx]["type"] in ("TIME","SIZE","COUNT")
        assert is_int(lo) and is_int(hi) and 0<=lo<=hi<K
        if op=="sum":
            return fields[idx]["type"], (lambda ctx,b,idx=idx,lo=lo,hi=hi: sum(ctx[i][idx] for i in range(lo,hi+1)))
        if op=="mean":
            return fields[idx]["type"], (lambda ctx,b,idx=idx,lo=lo,hi=hi: Fraction(sum(ctx[i][idx] for i in range(lo,hi+1)), hi-lo+1))
        if op=="min":
            return fields[idx]["type"], (lambda ctx,b,idx=idx,lo=lo,hi=hi: min(ctx[i][idx] for i in range(lo,hi+1)))
        assert op=="max"
        return fields[idx]["type"], (lambda ctx,b,idx=idx,lo=lo,hi=hi: max(ctx[i][idx] for i in range(lo,hi+1)))
    raise AssertionError("term")

def cmp_fn(c, K, fields, allow_dollar):
    assert set(c.keys()) == {"cmp","left","right"}
    op = c["cmp"]
    lt, lf = term_type(c["left"], K, fields, allow_dollar)
    rt, rf = term_type(c["right"], K, fields, allow_dollar)
    assert lt == rt
    if lt in ("ID","FLAG"): assert op in ("eq","ne")
    if op=="eq": return lambda ctx,b: lf(ctx,b)==rf(ctx,b)
    if op=="ne": return lambda ctx,b: lf(ctx,b)!=rf(ctx,b)
    if op=="lt": return lambda ctx,b: lf(ctx,b)<rf(ctx,b)
    if op=="le": return lambda ctx,b: lf(ctx,b)<=rf(ctx,b)
    if op=="gt": return lambda ctx,b: lf(ctx,b)>rf(ctx,b)
    assert op=="ge"
    return lambda ctx,b: lf(ctx,b)>=rf(ctx,b)

def atom_fn(a, K, fields):
    if "quantifier" in a:
        assert set(a.keys())=={"quantifier","from","to","predicate"}
        q=a["quantifier"]; lo=a["from"]; hi=a["to"]
        assert q in ("any","all") and is_int(lo) and is_int(hi) and 0<=lo<=hi<K
        pf = cmp_fn(a["predicate"], K, fields, True)
        if q=="any":
            return lambda ctx: any(pf(ctx,b) for b in range(lo,hi+1))
        return lambda ctx: all(pf(ctx,b) for b in range(lo,hi+1))
    f = cmp_fn(a, K, fields, False)
    return lambda ctx: f(ctx, None)

def main():
    data = sys.stdin.buffer.read()
    try:
        req = json.loads(data.decode("utf-8"))
    except Exception:
        die("E_JSON")
    K = req["window"]; fields = req["schema"]
    atoms = [atom_fn(a, K, fields) for a in req["atoms"]]
    def contexts(traces):
        out=[]
        for tr in traces:
            rows = sorted(tr["rows"], key=lambda r: r["t"])
            for i in range(len(rows)-K+1):
                out.append((tr["id"], tr["source"], rows[i+K-1]["t"], [r["values"] for r in rows[i:i+K]]))
        return out
    tr = contexts(req["train"]); pr = contexts(req["probes"]); qy = contexts(req["queries"])
    # literal values: lit = (atom, negated)
    def lit_val(lit, ctx):
        i, neg = lit
        v = atoms[i](ctx[3])
        return (not v) if neg else v
    A = len(atoms)
    B = req["policy"]["max_width"]; S = req["policy"]["min_support"]; W = req["policy"]["min_witness"]
    sources = []
    for t in req["train"]:
        if t["source"] not in sources: sources.append(t["source"])
    eligible = []
    if sources and pr:
        for size in range(1, B+1):
            for combo in combinations(range(A), size):
                for signs in __import__("itertools").product([False,True], repeat=size):
                    lits = list(zip(combo, signs))
                    # condition 2
                    ok = True
                    for s in sources:
                        cnt = sum(1 for c in tr if c[1]==s and all(lit_val(l,c) for l in lits))
                        if cnt < S: ok=False; break
                    if not ok: continue
                    # condition 3
                    if not all(any(lit_val(l,c) for l in lits) for c in tr): continue
                    # condition 4
                    for s in sources:
                        for idx in range(len(lits)):
                            cnt = sum(1 for c in tr if c[1]==s and lit_val(lits[idx],c) and all(not lit_val(l,c) for j,l in enumerate(lits) if j!=idx))
                            if cnt < W: ok=False; break
                        if not ok: break
                    if not ok: continue
                    # condition 5
                    if not any(not any(lit_val(l,c) for l in lits) for c in pr): continue
                    eligible.append(lits)
    classes = {}
    for lits in eligible:
        sigv = sum(1<<j for j,c in enumerate(pr) if any(lit_val(l,c) for l in lits))
        width = (len(pr)+3)//4
        sig = format(sigv,"x").rjust(width,"0")
        classes.setdefault(sig, []).append(lits)
    out_classes = []
    for sig, members in classes.items():
        rep = members[0]
        out_classes.append({"signature":sig, "members":len(members),
                            "representative":{"or":[{"atom":i,"negated":bool(n)} for i,n in rep]}})
    out_q = []
    for c in qy:
        must=0; may=0
        for sig, members in classes.items():
            falses = [all(not lit_val(l,c) for l in mem) for mem in members]
            if all(falses): must+=1
            if any(falses): may+=1
        status = "violating" if must>0 else ("ambiguous" if may>0 else "consistent")
        out_q.append({"trace":c[0],"end":c[2],"must":must,"may":may,"status":status})
    print(json.dumps({"version":1,"classes":out_classes,"queries":out_q}, separators=(",",":")))

main()
