class JsonError(Exception):
    """Input is not acceptable JSON (E_JSON)."""


class SchemaError(Exception):
    """Input is JSON but violates the request contract (E_SCHEMA)."""


class LimitError(Exception):
    """Input exceeds the maximum accepted size (E_LIMIT)."""


def is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


# --------------------------------------------------------------------------
# JSON level
# --------------------------------------------------------------------------


def _object_pairs(pairs):
    seen = set()
    for key, _value in pairs:
        if key in seen:
            raise JsonError("duplicate object key")
        seen.add(key)
    return dict(pairs)


def _bad_constant(name):
    raise JsonError("nonfinite number")


def depth_ok(node, limit=MAX_DEPTH):
    """True when no JSON container nests deeper than `limit`."""
    stack = [(node, 1)]
    while stack:
        item, depth = stack.pop()
        if isinstance(item, dict):
            if depth > limit:
                return False
            for value in item.values():
                if isinstance(value, (dict, list)):
                    stack.append((value, depth + 1))
        elif isinstance(item, list):
            if depth > limit:
                return False
            for value in item:
                if isinstance(value, (dict, list)):
                    stack.append((value, depth + 1))
    return True


def parse_request(data):
    if len(data) > MAX_INPUT_BYTES:
        raise LimitError("input too large")
    if data[:3] == b"\xef\xbb\xbf":
        raise JsonError("byte order mark")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise JsonError("invalid utf-8")
    try:
        request = json.loads(
            text, object_pairs_hook=_object_pairs, parse_constant=_bad_constant
        )
    except JsonError:
        raise
    except RecursionError:
        raise JsonError("nesting too deep")
    except Exception:
        raise JsonError("invalid json")
    if not depth_ok(request):
        raise JsonError("nesting too deep")
    return request


# --------------------------------------------------------------------------
# Validation helpers
# --------------------------------------------------------------------------


def require(cond):
    if not cond:
        raise SchemaError("schema violation")


def exact_keys(obj, keys):
    return isinstance(obj, dict) and set(obj.keys()) == set(keys)


