@staticmethod
def _literal_masks(atom_masks, total):
    """Masks over contexts for every literal (2*i positive, 2*i+1 negated)."""
    full = (1 << total) - 1 if total else 0
    masks = []
    for mask in atom_masks:
        masks.append(mask)
        masks.append(mask ^ full)
    return masks

# -- learning --------------------------------------------------------

def learn(self):
    """Return {signature: {"members": [literal tuples], "rep": literal tuple}}."""
    if not self.train_ctx or not self.probe_ctx:
        return {}

    train_total = len(self.train_ctx)
    probe_total = len(self.probe_ctx)
    train_all = (1 << train_total) - 1
    probe_all = (1 << probe_total) - 1

    src_masks = {name: 0 for name in self.train_sources}
    for index, ctx in enumerate(self.train_ctx):
        src_masks[ctx[1]] = src_masks.get(ctx[1], 0) | (1 << index)
    n_sources = len(src_masks)

    lit_train = self._literal_masks(self._atom_masks(self.train_ctx), train_total)
    lit_probe = self._literal_masks(self._atom_masks(self.probe_ctx), probe_total)

    S = self.min_support
    W = self.min_witness

    eligible = []
    for atom_index in range(len(self.atom_fns)):
        options = []
        for negated in (False, True):
            lit = 2 * atom_index + (1 if negated else 0)
            mask = lit_train[lit]
            ok = True
            for src_mask in src_masks.values():
                count = (mask & src_mask).bit_count()
                if count < S or count < W:
                    ok = False
                    break
            if ok:
                options.append(lit)
        eligible.append(options)

    usable = [i for i, options in enumerate(eligible) if options]
    if not usable:
        return {}

    width = min(self.max_width, len(usable))
    hex_width = (probe_total + 3) // 4
    found = {}
    for size in range(1, width + 1):
        for combo in combinations(usable, size):
            option_lists = [eligible[i] for i in combo]
            for lits in product(*option_lists):
                masks = [lit_train[lit] for lit in lits]
                union = 0
                for mask in masks:
                    union |= mask
                if union != train_all:
                    continue
                probe_union = 0
                for lit in lits:
                    probe_union |= lit_probe[lit]
                if (probe_all & ~probe_union) == 0:
                    continue
                ok = True
                for position in range(size):
                    others = 0
                    for other_position in range(size):
                        if other_position != position:
                            others |= masks[other_position]
                    essential = masks[position] & ~others
                    if essential.bit_count() < W * n_sources:
                        ok = False
                        break
                    for src_mask in src_masks.values():
                        if (essential & src_mask).bit_count() < W:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue
                signature = format(probe_union, "x").rjust(hex_width, "0")
                bucket = found.get(signature)
                if bucket is None:
                    found[signature] = [list(lits)]
                else:
                    bucket.append(list(lits))
    return found

# -- response --------------------------------------------------------

def build(self):
    self.validate()
    found = self.learn()

    classes = []
    structures = []
    for signature, member_lists in found.items():
        classes.append(
            {
                "signature": signature,
                "members": len(member_lists),
                "representative": {
                    "or": [
                        {"atom": lit // 2, "negated": bool(lit % 2)}
                        for lit in member_lists[0]
                    ]
                },
            }
        )
        structures.append(self._class_structure(member_lists))

    queries = self._evaluate_queries(structures)
    return {"version": 1, "classes": classes, "queries": queries}

@staticmethod
def _class_structure(member_lists):
    """Precompute member masks and per-literal 'lacks' masks for a class.

    `lacks[l]` has a bit set for every member of the class that does not
    contain literal `l`; intersecting those masks over the literals that
    hold on a query context yields exactly the members that fail there.
    """
    count = len(member_lists)
    full = (1 << count) - 1
    contains = {}
    lit_union = 0
    for index, lits in enumerate(member_lists):
        bit = 1 << index
        for lit in lits:
            contains[lit] = contains.get(lit, 0) | bit
            lit_union |= 1 << lit
    lacks = {lit: full ^ mask for lit, mask in contains.items()}
    return {
        "lit_union": lit_union,
        "full": full,
        "lacks": lacks,
        "count": count,
    }

